actions.action:
// Economic nexus established per Wayfair - CT filing required
// CT threshold: $500,000 in gross receipts (higher than typical)
// Apportionment will be calculated by tables 7000-7500

// No nexus - no CT filing required
apportionment.state_tax = 0.0;
apportionment.state_refund_or_owed = apportionment.state_payments;

            // Calculate CT state additions
            double additions = 0.0;

            // CT Addition 1: Federal bond interest (tax-exempt federally, taxable in CT)
            // Uncomment when federal_bond_interest field is available:
            // additions += revenue.federal_bond_interest;

            // CT Addition 2: IRC 199A deduction addback (CT does not conform)
            // Uncomment when section_199a_deduction field is available:
            // additions += result.section_199a_deduction;

            // CT Addition 3: Bonus depreciation addback (CT decouples from federal)
            // Uncomment when bonus_depreciation field is available:
            // additions += result.bonus_depreciation_total;

            apportionment.state_additions = additions;

            // Calculate CT state subtractions
            double subtractions = 0.0;

            // CT Subtraction 1: CT municipal bond interest
            // Uncomment when ct_municipal_interest field is available:
            // subtractions += revenue.ct_municipal_interest;

            // CT Subtraction 2: CT NOL deduction (if different from federal)
            // Uncomment when ct_nol_deduction field is available:
            // subtractions += result.ct_nol_deduction;

            // CT Subtraction 3: Dividend deduction for subsidiaries
            // Uncomment when dividend fields are available:
            // subtractions += result.ct_dividend_deduction;

            apportionment.state_subtractions = subtractions;

            // CT uses 7.5% flat rate on all corporate income
            apportionment.state_tax =
              apportionment.state_taxable_income * apportionment.state_tax_rate;

            // Subtract CT state credits (R&D, jobs, film, manufacturing, etc.)
            apportionment.state_tax =
              Math.max(0.0, apportionment.state_tax - apportionment.state_credits);

            // Calculate refund or amount owed
            apportionment.state_refund_or_owed =
              apportionment.state_payments - apportionment.state_tax;
